var s=[{title:`Mesurez l’emprise au sol`,text:`Notez la longueur et la largeur du sol dégagé, qui est généralement plus petit que la pièce elle-même. Un curl debout demande assez peu de place, alors qu’une fente marchée ou un exercice au sol peut demander de l’espace pour étendre bras et jambes. Laissez de la place supplémentaire autour des poids en mouvement et pensez à la façon dont l’exercice commence et se termine.`},{title:`Pensez en trois dimensions`,text:`Un squat ou un rowing debout demande de la place sur les côtés pour vos coudes et le matériel. Une pompe ou un dead bug demande un espace au sol aussi long que votre corps. Un swing de kettlebell demande un espace dégagé devant, derrière et autour du kettlebell, et les développés au-dessus de la tête ou les sauts demandent de la hauteur.`},{title:`Obstacles cachés`,text:`Faites attention aux tables basses, aux luminaires suspendus, aux angles saillants, aux radiateurs, aux animaux, aux câbles, aux tapis et aux portes qui s’ouvrent dans votre zone. Vérifiez que le sol reste antidérapant une fois votre tapis posé. Si vous arrivez tout juste à finir une répétition sans toucher un meuble, l’espace est trop étroit pour une séance complète.`},{title:`Un programme pour petits espaces`,text:`Dans un espace étroit, faites des squats bulgares sur place plutôt que des fentes marchées, et du travail du haut du corps assis ou au sol plutôt que de grands mouvements latéraux. Si la pièce est trop petite pour des portages chargés, faites des exercices anti-flexion latérale sur place. Gardez le schéma de mouvement et laissez l’exercice précis changer.`},{title:`Avec TrainUp`,text:`Saisissez la taille de votre espace au sol et la hauteur de votre plafond dans Profil. Le programme ne choisit alors que des exercices dont le mouvement, matériel compris, tient dans cet espace.`}];var a=[{label:`Bibliothèque d’exercices de l’ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic : sécurité et technique en musculation`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var u={sections:s,sources:a};export{u as default,s as sections,a as sources};